/*
 * UI control names for the action log — PURE, shared by the frontend (which names a click) and the
 * backend (which re-checks every name a client sends before printing it).
 *
 * A name is built ONLY from strings that appear literally in this app's source (ui-action-ids.gen.js,
 * regenerated by scripts/gen-action-names.mjs). A control whose test id carries something else (a
 * space key, a file id, a level a site defined) is reported by its fixed head and "*":
 *   "pd-close"               a static id
 *   "sv-decline-confirm"     a testId prop literal + a fixed tail
 *   "pd-tab-overview"        a templated id whose dynamic part is a code-defined id
 *   "cls-space-row-*"        a templated id whose dynamic part is data (never printed)
 *   "jv-row-*>button"        an unnamed control inside a named one ("button", "tab", "link", ...)
 *   "pd-close~3"             the same control pressed 3 times in a row
 */
import { STATIC, PREFIXES, SUFFIXES, LITERALS } from "./ui-action-ids.gen.js";

const S = new Set(STATIC);
const SUF = new Set(SUFFIXES);
const LIT = new Set(LITERALS);
const PRE = [...PREFIXES].sort((a, b) => b.length - a.length); // longest head first
const BASES = [...STATIC].sort((a, b) => b.length - a.length);
export const ROLES = Object.freeze(["button", "link", "tab", "menuitem", "option", "checkbox", "radio", "switch", "summary"]);
const ROLE_SET = new Set(ROLES);
export const MAX_TRAIL = 20;
const MAX_REPEAT = 999;

/** The loggable name of a test id / data-lz value, or null when nothing of it may be printed. */
export function nameOfId(id) {
  if (typeof id !== "string" || id.length === 0 || id.length > 120) return null;
  if (S.has(id)) return id;
  for (const base of BASES) {
    if (id.length > base.length + 1 && id.startsWith(base + "-")) {
      const rest = id.slice(base.length + 1);
      return SUF.has(rest) || LIT.has(rest) ? id : `${base}-*`;
    }
  }
  for (const head of PRE) {
    if (id.length > head.length && id.startsWith(head)) {
      const rest = id.slice(head.length);
      return LIT.has(rest) ? id : `${head}*`;
    }
  }
  return null;
}

/**
 * Is `entry` (as a client sent it) exactly something nameOfId could have produced, plus the optional
 * ">role" and "~count"? The backend prints a trail entry only when this says yes.
 */
export function isKnownName(entry) {
  if (typeof entry !== "string" || entry.length > 140) return false;
  let s = entry;
  const rep = s.match(/~(\d{1,3})$/);
  if (rep) { const n = Number(rep[1]); if (n < 2 || n > MAX_REPEAT) return false; s = s.slice(0, -rep[0].length); }
  const role = s.match(/>([a-z]+)$/);
  if (role) { if (!ROLE_SET.has(role[1])) return false; s = s.slice(0, -role[0].length); }
  if (s.endsWith("-*")) {
    const head = s.slice(0, -1); // "x-"
    return S.has(head.slice(0, -1)) || PREFIXES.includes(head);
  }
  return nameOfId(s) === s;
}

/** PURE. Append `name` to `trail` (collapsing an immediate repeat into "~n"), newest MAX_TRAIL kept. */
export function pushName(trail, name) {
  const out = Array.isArray(trail) ? trail.slice() : [];
  if (!name) return out;
  const last = out[out.length - 1];
  if (last) {
    const m = last.match(/^(.*?)(?:~(\d{1,3}))?$/);
    if (m && m[1] === name) {
      const n = Math.min(MAX_REPEAT, (Number(m[2]) || 1) + 1);
      out[out.length - 1] = `${name}~${n}`;
      return out;
    }
  }
  out.push(name);
  return out.length > MAX_TRAIL ? out.slice(out.length - MAX_TRAIL) : out;
}

/** PURE. A trail as received: only known names survive, at most MAX_TRAIL; `dropped` counts the rest. */
export function cleanTrail(raw) {
  if (!Array.isArray(raw)) return { trail: [], dropped: raw == null ? 0 : 1 };
  const trail = [];
  let dropped = 0;
  for (const e of raw.slice(-MAX_TRAIL)) { if (isKnownName(e)) trail.push(e); else dropped++; }
  dropped += Math.max(0, raw.length - MAX_TRAIL);
  return { trail, dropped };
}
